arguments.command:
cd /tmp/vally-eval-trial-XsEtnZ && P=.copilot-tracking/skraft-plans/pricing && mkdir -p $P/features $P/details/2026-11-11 $P/evidence/2026-11-11/discount tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > $P/features/pricing-loyalty-discount.feature <<'EOF'
@loyalty-discount
Feature: Loyalty tier discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: Bronze, Silver and Gold (AC-1 to AC-4), values copied from ac.md.
  # NOT DECIDED: Platinum tier. The business has not agreed a reduction, so no
  # scenario exists for it. Do not infer a value; escalate to DISCUSS.

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer with a tiny basket gets a reduction on a whole cent in their favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
EOF
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'EOF'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Fact]
    public void Bronze_customer_is_charged_the_Bronze_price()
    {
        // Bronze customer is charged the Bronze price (AC-1)
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }
}
EOF
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" > $P/evidence/2026-11-11/discount/acceptance-red.stdout 2>&1; echo $? > $P/evidence/2026-11-11/discount/acceptance-red.exit; git rev-parse HEAD > $P/evidence/2026-11-11/discount/acceptance-red.rev
cat $P/evidence/2026-11-11/discount/acceptance-red.exit; tail -25 $P/evidence/2026-11-11/discount/acceptance-red.stdout

